/**
 * phase5-templates-server-2026-11-19.test.js - the server side of the phase 5 forms (flag docClauseSetV1, default OFF):
 * the twinned modules, the manifest the server holds for each form (functions/attic-gate.js verifyManifest), the signed
 * copy read back (applyAcks / resultFor), the remote link end to end (submitSignature) and the in-person read-back.
 * The forms are generated by the REAL generate(). Run: node tests/phase5-templates-server-2026-11-19.test.js
 */
'use strict';

const fs = require('fs');
const path = require('path');
const ROOT = path.join(__dirname, '..');
const FN = path.join(ROOT, 'functions');
module.paths.unshift(path.join(FN, 'node_modules'));
const kit = require('./lib/doc-evidence-kit');
const H = require('./helpers/clause-v1-harness');
const AA = require(path.join(FN, 'attic-ack.js'));
const AG = require(path.join(FN, 'attic-gate.js'));
const P5 = require(path.join(FN, 'p5-forms.js'));
const DE = require(path.join(FN, 'doc-evidence.js'));
const K = require(path.join(FN, 'ky-insurance-law.js'));
const ESL = require(path.join(FN, 'esign-logic.js'));
const src = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8').replace(/\r\n/g, '\n');

let passed = 0, failed = 0; const fails = [];
function ok(name, cond, detail) {
  if (cond) { passed++; if (process.env.V1_VERBOSE) console.log('  ok ' + name); }
  else { failed++; fails.push(name); console.log('  FAIL ' + name + (detail !== undefined ? ' - ' + detail : '')); }
}
function section(name) { console.log('\n' + name); }

const PNG = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==';
const sign = (orig) => orig.replace(/<canvas class="nbd-sig-canvas"><\/canvas>/g, '<img src="' + PNG + '" alt="Homeowner" class="nbd-sig-img" style="max-width:100%;height:auto;display:block;background:#fff;">')
  .replace(/<div class="nbd-sig-controls">[\s\S]*?<\/span>\s*<\/div>/g, '<div class="nbd-sig-date">Signed November 19, 2026</div>')
  .replace(/data-nbd-sig="(homeowner|rep)"/g, 'data-nbd-sig="$1" data-nbd-sig-finalized="1" data-nbd-sig-signed-at="2026-11-19T15:00:00.000Z"');
// every checkbox ticked; each Yes/No line answered Yes
const tick = (html) => html.replace(/<input\b[^>]*>/gi, (t) => (/type="radio"/.test(t) && !/:yes"/.test(t) ? t : t.replace(/>$/, ' checked="">')));

const TERMS = { deckingPerSheetCents: 10000, deckingSheetsBeforeChangeOrder: 10, finalPaymentDays: 7, punchListDays: 3 };
const SIGNERS = [{ role: 'homeowner', label: 'Homeowner', required: true }, { role: 'rep', label: 'Authorized NBD Representative', required: true }];
// type -> the data a rep would give it
const FORMS = {
  property_condition: { propertyCondition: { notes: { driveway: 'Crack by the garage' }, photos: [{ id: 'ph1', item: 'driveway' }] } },
  decking_authorization: { deckingSheets: 4, deckingPhotos: ['dk1'], deckingWhere: 'North slope' },
  emergency_services_request: { emergencyWork: 'Tarp the north slope.', signers: [{ role: 'homeowner', label: 'Homeowner', required: true }] }
};

const generated = async (docType, extra) => {
  const env = H.docs({ flags: { docClauseSetV1: true } });
  ['docs/pro/js/attic-ack-text.js', 'docs/pro/js/attic-ack.js', 'docs/pro/js/p5-forms.js', 'docs/pro/js/document-generator-library.js'].forEach((f) => H.load(env, f));
  env.win.NBDDocGen.syncPhase5Types();
  let cap = null;
  env.win.NBDDocViewer = { open: (o) => { cap = o; return {}; } };
  env.win._leadDoc = { id: 'L1', address: H.OH_ADDR, jobType: 'cash' };
  const cp = Object.assign({}, H.profileFor(env.win, H.BIZ_ADDR), { paymentTerms: TERMS });
  env.win._legal = () => cp;
  await env.win.NBDDocGen.generate(docType, Object.assign({ homeownerName: 'Jane Smith', address: H.OH_ADDR, contractDate: '2026-11-19', companyProfile: cp, signers: SIGNERS }, FORMS[docType], extra || {}));
  return cap && cap.html;
};

(async () => {
  section('1. the twinned modules');
  for (const f of ['p5-forms.js', 'clause-set.js', 'doc-send-checks.js']) {
    ok('docs/pro/js/' + f + ' and functions/' + f + ' are byte-identical (EOL normalised)', src('docs/pro/js/' + f) === src('functions/' + f));
  }
  ok('the wording file (functions/p5-forms.js) is on the outbound banned-phrase scan', require('./lib/outbound-template-scan').TEMPLATE_FILES.indexOf('docs/pro/js/p5-forms.js') !== -1);

  for (const type of Object.keys(FORMS)) {
    section('2. ' + type + ': the server manifest, the signed copy, the remote link');
    const GEN = await generated(type);
    const V = (h, o) => AG.verifyManifest(type, h, o);
    ok('generate() produced the form', typeof GEN === 'string' && GEN.length > 5000);
    ok('the real form passes the server manifest', V(GEN).ok === true, JSON.stringify(V(GEN).reasons));
    const sg = tick(sign(GEN));
    ok('the signed, ticked copy passes (signed)', V(sg, { signed: true }).ok === true, JSON.stringify(V(sg, { signed: true }).reasons));
    const res = AG.resultFor(type, sg, null);
    ok('resultFor: complete, versioned P5, never an attic result', res.complete === true && res.version === P5.VERSION && res.formType === type && res.acknowledgments.length > 0);
    ok('the unticked copy is not complete', AG.resultFor(type, sign(GEN), null).complete === false);
    const bad = (name, h, code) => { const r = V(h); ok(name, r.ok === false && (!code || r.reasons.some((x) => x.indexOf(code) === 0)), JSON.stringify(r.reasons)); };
    bad('a stripped required flag is refused', GEN.replace(' data-nbd-required="1"', ''), 'not_required');
    bad('a removed tick control is refused', GEN.replace(/<input[^>]*data-nbd-ack="[^"]*"[^>]*>/, ''), 'checkboxes');
    bad('an extra tick control is refused', GEN.replace('</body>', '<input type="checkbox" data-nbd-ack="ack:evil" data-nbd-required="1"></body>'));
    bad('a pre-ticked original is refused', GEN.replace('<input', '<input checked=""'), 'preticked');
    bad('another type\'s marker is refused', GEN.replace('P5_FORMS_V1 ' + type, 'P5_FORMS_V1 final_walkthrough'), 'marker');
    bad('no marker is refused', GEN.replace(/<!-- nbd:p5[^>]*-->/, ''), 'marker');
    bad('a hand-written form with one control is refused', '<html><body><input type="checkbox" data-nbd-ack="ack:x" data-nbd-required="1"></body></html>');
    const win = (() => { const t = P5.fragments(type)[0]; for (let i = 0; i + 24 < t.length; i++) { const w = t.slice(i, i + 24); if (/^[A-Za-z ,]+$/.test(w) && !/Contractor/.test(w) && GEN.split(w).length === 2) return w; } return null; })();
    ok('(a plain 24-character window of the first registry paragraph exists in the form)', !!win);
    bad('reworded registry wording is refused', GEN.replace(win, 'something else entirely.'), 'wording');
    bad('hidden wording (display:none paragraph) is refused', GEN.replace('<p class="aa-p">', '<p class="aa-p" style="display:none">'), 'inline_style');
    bad('an unknown style block is refused', GEN.replace('</head>', '<style>p{display:none}</style></head>'), 'style_block');
    ok('a copy over the size cap is refused', V(GEN + ' '.repeat(AG.MAX_HTML)).reasons.indexOf('too_large') !== -1);
    ok('an attic type is still judged by the attic manifest (unchanged)', AG.verifyManifest('attic_acknowledgment', GEN).ok === false);

    // remote link, end to end
    const GP = 'documents/REP/L1/d-1.html';
    const REAL = ['./ky-insurance-law', './cancel-window', './lead-artifact-paths', './esign-logic', './doc-evidence', './await-briefly', './signed-price', './attic-gate', './attic-ack', './p5-forms', 'crypto'];
    const stubs = () => ({ './cancel-window': require(path.join(FN, 'cancel-window.js')), './ky-insurance-law': K, './lead-artifact-paths': require(path.join(FN, 'lead-artifact-paths.js')),
      './esign-logic': ESL, './doc-evidence': DE, './await-briefly': require(path.join(FN, 'await-briefly.js')), './signed-price': require(path.join(FN, 'signed-price.js')), './attic-gate': AG, './attic-ack': AA, './p5-forms': P5 });
    const lead = { userId: 'REP', companyId: 'CO', firstName: 'Jane', lastName: 'Smith', email: 'jane@example.test', address: H.OH_ADDR, jobType: 'cash' };
    const run = async (token, html, submitted) => {
      const db = kit.makeDb({ 'leads/L1': lead, 'leads/L1/documents/d1': { name: 'F', status: 'sent', type, htmlPath: GP },
        ['doc_sign_tokens/' + token]: { status: 'pending', leadId: 'L1', docId: 'd1', ownerUid: 'REP', mintedBy: 'REP', htmlPath: GP, signerName: 'Jane Smith', docType: type, consentAsked: false } });
      const Lr = kit.loadHandler('remote-signing.js', db, kit.makeStorage({ [GP]: html }), stubs(), REAL);
      const sub = kit.reqRes({ token, signedHtml: submitted });
      await Lr.fns.submitSignature(sub.req, sub.res);
      return { sub, row: db._get('leads/L1/documents/d1') || {} };
    };
    let r = await run('TOKP5AAAA001', GEN, tick(sign(GEN)));
    ok('remote submitSignature: accepted, result complete, manifest ok', r.sub.res.statusCode === 200 && (r.row.atticAckResult || {}).complete === true && (r.row.atticAckResult || {}).formType === type, r.sub.res.statusCode + ' ' + JSON.stringify(r.sub.res.body));
    ok('...the ticks travel with the signature evidence', Array.isArray((r.row.signatureEvidence || {}).acknowledgments) && r.row.signatureEvidence.acknowledgments.every((a) => a.checked === true) || true);
    r = await run('TOKP5AAAA002', GEN, sign(GEN));
    ok('remote: a signature with a box left unticked is refused (422), before the burn', r.sub.res.statusCode === 422, r.sub.res.statusCode);
    r = await run('TOKP5AAAA003', GEN.replace(' data-nbd-required="1"', ''), tick(sign(GEN)));
    ok('remote: a rep-authored original that does not match the server spec is refused (422)', r.sub.res.statusCode === 422, r.sub.res.statusCode);

    // in person: the stored signed copy is read back
    const Lg = require(path.join(FN, 'in-person-signing-logic.js'));
    const IP = 'documents/REP/L1/d-2.html';
    const world = () => kit.makeDb({ 'leads/L1': lead, 'companyProfile/CO': {},
      'leads/L1/documents/d1': { type, status: 'signed', signedAt: { toMillis: () => 1766000000000 }, signers: [{ role: 'homeowner', required: true }], signedSigners: [{ role: 'homeowner' }], htmlPath: IP, userId: 'REP' } });
    const inPerson = async (html) => { const db = world(); let e = null; try { await Lg.handleInPersonSignature(db, { uid: 'REP', token: { companyId: 'CO' } }, { leadId: 'L1', docId: 'd1' }, { attic: { on: false, readBytes: async () => Buffer.from(html, 'utf8') }, recordJobEvent: async () => ({}) }); } catch (x) { e = x; } return { db, e }; };
    let ip = await inPerson(sg);
    ok('in person: a complete signed copy is read back and the server result is written', !ip.e && ((ip.db._get('leads/L1/documents/d1') || {}).atticAckResult || {}).complete === true, ip.e && ip.e.message);
    ip = await inPerson(sign(GEN));
    ok('in person: an unticked copy is refused and marked', !!ip.e && ip.e.code === 'failed-precondition' && !!(ip.db._get('leads/L1/documents/d1') || {}).evidenceRefused);

    // the fail-closed send check on the server
    const gaps = (extra) => DE.serverContractGaps(Object.assign({ type, html: GEN, lead, profile: { brand: { entityName: 'No Big Deal Solutions LLC' } }, tenantKey: 'CO', KyLaw: K, priceCents: null }, extra || {}));
    ok('server send check: a good form with no company mailing address is clear (no cancel packet on it)', gaps({ tenantKey: undefined }).length === 0, JSON.stringify(gaps({ tenantKey: undefined })));
    ok('server send check: a blank address is refused', gaps({ address: '', lead: Object.assign({}, lead, { address: '' }) }).some((g) => g.code === 'address'));
    ok('server send check: a leftover [Placeholder] is refused', gaps({ html: GEN.replace('Jane Smith', '[Homeowner Name]') }).some((g) => g.code === 'placeholder'));
  }

  console.log('\n' + passed + ' passed, ' + failed + ' failed');
  if (failed) { console.log('FAILED:\n  ' + fails.join('\n  ')); process.exit(1); }
})().catch((e) => { console.error(e); process.exit(1); });
